let mainradius = 700;
let Yangle = 0;
let speed = 0.01;
let offset = 0;
let ring = 4;

function setup() {
	createCanvas(1112, 834, WEBGL);
	colorMode(HSB, 255);
	frameRate(40);
}

function draw() {
	if (keyPressed) {
		if (key == CODED) {
			if (keyCode == UP) {
				ring += 1;
			}
			if (keyCode == DOWN) {
				if (ring > 1) {
					ring -= 1;
				}
			}
		}
	}
	background(0);
	translate(0.9*width/2, 0.85*height/2);
	rotateY(Yangle);
	rotateX(-5);
	rotateZ(-0);
	for (y = -mainradius; y < mainradius; y += round(ring)) {
		strokeWeight(ring * sin(y + offset));
		let t = random(1);
		while (t < TWO_PI) {
			let radius = sqrt(pow((mainradius - 60) / 2, 2) - pow(y, 2));
			let x = radius * cos(t);
			let z = radius * sin(t);
			//stroke(map(sin(y + offset), -1, 1, 0, 255), 200, 255);
			stroke(abs(y), 200, 255);
			//if random(1)=0 {
				//n=x
			//} else if {
				//n=z
			//}
			point(random(300), random(300), random(300));
			t += 0.1;
		}
	}
	Yangle += speed;
	offset += 0.05;
}

